# Regenerated by .github/workflows/release.yml on every tagged release, so the
# version and checksums below always match the published assets.
#
# The published asset is a Nuitka standalone build: compiled, so there is no
# interpreter and no readable source on disk. It is deliberately not a Nuitka
# *onefile* binary — onefile unpacks its whole payload on every single run, which
# made even `bib --help` take about four seconds. The directory form does not
# unpack anything and starts in well under a second.
class Bib < Formula
  desc "A real, unmanaged browser in a box — a Linux container or a macOS VM"
  homepage "https://github.com/sapn95/browser-in-a-box"
  version "3.1.1"
  license "MIT"

  on_macos do
    on_intel do
      # Only the container variant would work here anyway, and no Intel Mac binary
      # is published; say so instead of failing with a missing url.
      odie "bib ships macOS binaries for Apple silicon only; run ./bib.py from a checkout"
    end

    on_arm do
      url "https://github.com/sapn95/browser-in-a-box/releases/download/v3.1.1/bib-macos-arm64.tar.gz"
      sha256 "cb58f6550d1bfeb99260ebc86761ca437e4034e7b3757a2d385a0e53df3ec527"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/sapn95/browser-in-a-box/releases/download/v3.1.1/bib-linux-arm64.tar.gz"
      sha256 "91c6685b659654ee9a8c9c2d78ba17a7a8404d9aee63b4e2a19176766d7071f0"
    end
    on_intel do
      url "https://github.com/sapn95/browser-in-a-box/releases/download/v3.1.1/bib-linux-x86_64.tar.gz"
      sha256 "929a574d3c9c718bf5be8bd5dba47e8dd0eb3e2bd110a865db7d10a4101256ab"
    end
  end

  def install
    libexec.install Dir["*"]
    bin.install_symlink libexec/"bib"
  end

  test do
    assert_match "bib #{version}", shell_output("#{bin}/bib --version")
  end
end
